<?php $pay=$page['payment_details'];$sale=$page['sale_record'];$balance=bcsub(bcsub($sale['total_amount'],$pay['credited'],2),$pay['settled'],2);$toCover=bcsub($balance,$pay['pending'],2); ?>
<section class="contact-sheet direct-payment" id="registrar-cobro"><h2>Cobros de esta venta</h2>
<div class="direct-metrics"><div><?= bccomp($balance,'0',2)<0?'Saldo a favor del cliente':'Saldo sin confirmar' ?><strong><?= $e((bccomp($balance,'0',2)<0?bcsub('0',$balance,2):$balance).' '.$sale['currency_code']) ?></strong></div><div>En revisión<strong><?= $e($pay['pending'].' '.$sale['currency_code']) ?></strong></div><div>Por cubrir<strong><?= $e((bccomp($toCover,'0',2)>0?$toCover:'0.00').' '.$sale['currency_code']) ?></strong></div></div>
<?php if(isset($_GET['payment_registered'])): ?><p class="notice">Cobro registrado para revisión del jefe. No se confirmó automáticamente.</p><?php endif; ?>
<?php if(permissionHas('venta_directa.sales','register_payment')&&permissionHas('contabilidad.customer_invoices','register_payment')&&$sale['invoice_status']==='posted'&&bccomp($toCover,'0',2)>0): ?>
<details <?= ($_POST['action']??'')==='direct_payment'?'open':'' ?>><summary class="contact-button">Registrar cobro total o parcial</summary>
<form method="post" enctype="multipart/form-data" action="index.php?id=<?= (int)$detail['id'] ?>" class="direct-simple-form" data-direct-payment>
<input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><input type="hidden" name="action" value="direct_payment"><input type="hidden" name="request_key" value="<?= $e($page['input']['request_key']??$page['key']) ?>"><input type="hidden" name="version" value="<?= (int)$sale['invoice_version'] ?>">
<label>Importe recibido *<input name="amount" inputmode="decimal" value="<?= $e($page['input']['amount']??$toCover) ?>" required></label>
<label>Moneda<select name="currency_code"><?php foreach(array_unique(array_merge(accountingCurrencyCodes($page['settings']),[$sale['currency_code']])) as $code): ?><option <?= $code===($page['input']['currency_code']??$sale['currency_code'])?'selected':'' ?>><?= $e($code) ?></option><?php endforeach; ?></select></label>
<label>Fecha del cobro<input type="date" name="payment_date" value="<?= $e($page['input']['payment_date']??commerceToday()) ?>" max="<?= commerceToday() ?>" required></label>
<label>Cuenta de ingreso *<select name="account_id" required><option value="">Selecciona la caja o banco</option><?php foreach($page['accounts'] as $account): ?><option value="<?= (int)$account['id'] ?>" <?= (int)($page['input']['account_id']??0)===(int)$account['id']?'selected':'' ?>><?= $e($account['name'].' · '.($account['currency_code']?:'Multimoneda')) ?></option><?php endforeach; ?></select></label>
<label>Medio de pago *<select name="method_id" required><option value="">Selecciona el medio</option><?php foreach($page['methods'] as $method): ?><option value="<?= (int)$method['id'] ?>" <?= (int)($page['input']['method_id']??0)===(int)$method['id']?'selected':'' ?>><?= $e($method['name']) ?></option><?php endforeach; ?></select></label>
<label>Referencia<input name="reference" maxlength="160" value="<?= $e($page['input']['reference']??'') ?>"></label>
<label>Comprobante (foto o PDF)<input type="file" name="proof_files[]" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf" multiple></label>
<p>La tasa actual se utiliza si cobras en otra moneda. El cobro quedará pendiente de validación; puedes registrar varios abonos sin superar el saldo.</p><button class="contact-button contact-button-primary" type="submit">Registrar cobro</button></form></details>
<?php endif; ?>
<?php foreach($pay['payments'] as $payment): ?><div class="direct-history-row"><span><?= $e($payment['payment_date'].' · '.$payment['reference']) ?><small><?= $e(['pending'=>'En revisión','settled'=>'Confirmado','cancel'=>'Cancelado'][$payment['status']]??$payment['status']) ?></small></span><strong><?= $e($payment['amount'].' '.$sale['currency_code']) ?></strong></div><?php endforeach; ?>
</section>
